// ── Native orbit camera (drop-to-view) ──────────────────────────────────────────
// A <Scene3D.Camera nativeCamera> hands camera control to the HOST: the cart never
// re-renders to MOVE the camera — drag orbits, wheel dollies, and the host redraws on
// markDirty. That sidesteps the per-frame React-rerender churn that made the loader
// pane choppy (see the loader_pane_camera memory). The door layer feeds raw input
// deltas in (orbitDrag/orbitZoom); orbitFrame seeds it on model load so an
// arbitrary-scale import always lands framed in view.
pub const Orbit = struct {
    yaw: f32 = 0.7, // radians around +Y
    pitch: f32 = 0.45, // radians above the XZ plane
    dist: f32 = 6,
    target: [3]f32 = .{ 0, 0, 0 },
    radius: f32 = 1,
    framed: bool = false,
    // Camera lock (req_2893): freeze the view where the user set it. Gates EVERY
    // user-motion entry (drag/zoom/pan/double-click focus/compass snap) at the one
    // place they all funnel through, so the JS doors AND engine.zig's native input
    // loop are covered by the same switch. orbitFrame (model load) stays live — a
    // fresh model must land in view even under lock.
    locked: bool = false,
    navigation_enabled: bool = false,
    navigation_keys: u8 = 0,
    navigation_shift: bool = false,
    navigation_ctrl: bool = false,
};

pub const ORBIT_NAVIGATION_TUNING = struct {
    /// Travel scales with the current dolly distance so close detail work stays
    /// precise while a framed large model remains quick to cross.
    pub const distance_per_second: f32 = 0.7;
    pub const radius_floor_per_second: f32 = 0.08;
    pub const fast_multiplier: f32 = 4.0;
    pub const precision_multiplier: f32 = 0.15;
    /// A debugger pause or window hitch must not teleport the camera on resume.
    pub const maximum_step_seconds: f32 = 0.05;
};

pub const ORBIT_CLIP_TUNING = struct {
    /// Keep the far plane clear of the estimated mesh sphere instead of placing
    /// it exactly on the last surface, where float and bound error can flicker.
    pub const surface_padding_radii: f32 = 0.25;
    pub const minimum_surface_padding: f32 = 1.0;
};

const NAV_FORWARD: u8 = 1 << 0;
const NAV_BACK: u8 = 1 << 1;
const NAV_LEFT: u8 = 1 << 2;
const NAV_RIGHT: u8 = 1 << 3;
const NAV_UP: u8 = 1 << 4;
const NAV_DOWN: u8 = 1 << 5;

pub fn orbitNavigationEnabled() bool {
    return z3d.g_orbit.navigation_enabled;
}

/// Tab is shell-owned; this is the strict native mode boundary it toggles. Key
/// state is always cleared at a transition so a held key cannot leak across modes.
pub fn orbitNavigationSet(enabled: bool) bool {
    z3d.g_orbit.navigation_enabled = enabled;
    z3d.g_orbit.navigation_keys = 0;
    z3d.g_orbit.navigation_shift = false;
    z3d.g_orbit.navigation_ctrl = false;
    return enabled;
}

fn navigationKeyMask(sym: i32) u8 {
    return switch (sym) {
        'w', 'W' => NAV_FORWARD,
        's', 'S' => NAV_BACK,
        'a', 'A' => NAV_LEFT,
        'd', 'D' => NAV_RIGHT,
        'z', 'Z' => NAV_UP,
        'x', 'X' => NAV_DOWN,
        else => 0,
    };
}

/// Capture one physical WASD/Z/X edge while navigation is enabled. Returning true is
/// the engine's instruction not to forward that edge to Studio's command keymap.
pub fn orbitNavigationKey(sym: i32, down: bool, shift: bool, ctrl: bool) bool {
    if (!z3d.g_orbit.navigation_enabled) return false;
    z3d.g_orbit.navigation_shift = shift;
    z3d.g_orbit.navigation_ctrl = ctrl;
    const mask = navigationKeyMask(sym);
    if (mask == 0) return false;
    if (down) z3d.g_orbit.navigation_keys |= mask else z3d.g_orbit.navigation_keys &= ~mask;
    return true;
}

/// Host-side held-key integrator. The orbit eye and target translate together,
/// retaining the current yaw/pitch/dolly while WASD moves over the XZ work plane
/// and Z/X rise or descend on world Y.
pub fn orbitNavigationTick(dt_raw: f32) bool {
    if (!z3d.g_me_capture or !z3d.g_orbit.navigation_enabled or z3d.g_orbit.locked or
        z3d.g_orbit.navigation_keys == 0 or !std.math.isFinite(dt_raw) or dt_raw <= 0)
        return false;

    var forward: f32 = 0;
    var strafe: f32 = 0;
    var vertical: f32 = 0;
    if (z3d.g_orbit.navigation_keys & NAV_FORWARD != 0) forward += 1;
    if (z3d.g_orbit.navigation_keys & NAV_BACK != 0) forward -= 1;
    if (z3d.g_orbit.navigation_keys & NAV_RIGHT != 0) strafe += 1;
    if (z3d.g_orbit.navigation_keys & NAV_LEFT != 0) strafe -= 1;
    if (z3d.g_orbit.navigation_keys & NAV_UP != 0) vertical += 1;
    if (z3d.g_orbit.navigation_keys & NAV_DOWN != 0) vertical -= 1;
    const input_length = @sqrt(forward * forward + strafe * strafe + vertical * vertical);
    if (input_length <= 0) return false;
    forward /= input_length;
    strafe /= input_length;
    vertical /= input_length;

    const yaw = z3d.g_orbit.yaw;
    const view_forward = [3]f32{ -@sin(yaw), 0, -@cos(yaw) };
    const view_right = [3]f32{ @cos(yaw), 0, -@sin(yaw) };
    const base_speed = @max(
        z3d.g_orbit.dist * ORBIT_NAVIGATION_TUNING.distance_per_second,
        z3d.g_orbit.radius * ORBIT_NAVIGATION_TUNING.radius_floor_per_second,
    );
    // Precision wins if both modifiers are held: an accidental Shift must never
    // defeat the user's explicit fine-positioning chord.
    const speed_multiplier = if (z3d.g_orbit.navigation_ctrl)
        ORBIT_NAVIGATION_TUNING.precision_multiplier
    else if (z3d.g_orbit.navigation_shift)
        ORBIT_NAVIGATION_TUNING.fast_multiplier
    else
        1.0;
    const speed = base_speed * speed_multiplier;
    const step = speed * @min(dt_raw, ORBIT_NAVIGATION_TUNING.maximum_step_seconds);
    z3d.g_orbit.target[0] += (view_forward[0] * forward + view_right[0] * strafe) * step;
    z3d.g_orbit.target[1] += vertical * step;
    z3d.g_orbit.target[2] += (view_forward[2] * forward + view_right[2] * strafe) * step;
    return true;
}

pub fn residentMutationAllowed(domain: historical_preview.ResidentMutationDomain) bool {
    return z3d.g_historical_preview.allowsResidentMutation(domain);
}

/// Set the mesh editor's camera lock (req_2893 — `__model_orbit_lock`).
pub fn orbitSetLocked(on: bool) void {
    z3d.g_orbit.locked = on;
}

// View bookmarks (req_3067/req_3074): the host's job is the POSE — read it out, apply
// one back. The bookmark LIST is authored data and lives cart-side (ModelView state +
// hot twig), where naming/removal/ordering belong. This replaced the one-slot
// store/recall doors the moment the user wanted more than one pin.

/// Read the orbit pose (`__model_cam_pose`): yaw, pitch, dist, target xyz.
pub fn orbitPose() [6]f32 {
    return .{ z3d.g_orbit.yaw, z3d.g_orbit.pitch, z3d.g_orbit.dist, z3d.g_orbit.target[0], z3d.g_orbit.target[1], z3d.g_orbit.target[2] };
}
/// Apply a bookmarked orbit pose (`__model_cam_set_pose`). False under the req_2893
/// lock — applying a bookmark is a camera motion like any other. radius/framed/locked
/// stay live: they belong to the current model/session, not the view. Inputs are
/// clamped like the drag path so a hand-edited twig can never wedge the camera.
pub fn orbitSetPose(yaw: f32, pitch: f32, dist: f32, target: [3]f32) bool {
    if (z3d.g_orbit.locked) return false;
    z3d.g_orbit.yaw = yaw;
    z3d.g_orbit.pitch = std.math.clamp(pitch, -z3d.ORBIT_PITCH_LIM, z3d.ORBIT_PITCH_LIM);
    z3d.g_orbit.dist = @max(0.01, dist);
    z3d.g_orbit.target = target;
    return true;
}

/// Seed the orbit to frame a model of bounding `radius` about `target`. Called by the
/// load door the moment a model finishes parsing.
pub fn orbitFrame(target: [3]f32, radius: f32) void {
    z3d.g_orbit.target = target;
    z3d.g_orbit.radius = @max(1e-3, radius);
    z3d.g_orbit.dist = z3d.g_orbit.radius * 2.6;
    z3d.g_orbit.framed = true;
}

pub fn meshLiveFrame() ?mesh_edit.SelectionFrame {
    const verts = z3d.g_edit_verts orelse return null;
    return mesh_edit.frameForInterleavedPositions(verts[0 .. @as(usize, z3d.g_edit_count) * 8]);
}

/// Deterministic automation framing. Unlike load-time orbitFrame, an authored
/// camera command respects the lock and reports rejection instead of appearing to
/// succeed while the view stays put.
pub fn orbitFrameCurrent(selection: bool) bool {
    if (z3d.g_orbit.locked) return false;
    const frame = (if (selection) mesh_edit.selectionFrame() else z3d.meshLiveFrame()) orelse return false;
    z3d.orbitFrame(frame.center, frame.radius);
    return true;
}
/// Pitch clamp shy of the poles — straight-down is degenerate for a Y-up orbit (the
/// view basis loses its right vector). Shared by drag AND the compass axis snaps so a
/// snapped view is always reachable by dragging too.
pub const ORBIT_PITCH_LIM: f32 = 1.5;
/// Orbit by a screen-space drag delta (pixels). Pitch clamps shy of the poles.
pub fn orbitDrag(dx: f32, dy: f32) void {
    if (z3d.g_orbit.locked) return;
    z3d.g_orbit.yaw -= dx * 0.01;
    z3d.g_orbit.pitch += dy * 0.01;
    z3d.g_orbit.pitch = @max(-z3d.ORBIT_PITCH_LIM, @min(z3d.ORBIT_PITCH_LIM, z3d.g_orbit.pitch));
}
/// Dolly in/out by a wheel delta (sign only matters). Clamped to a sane band of the
/// model radius so you can't fly through it or lose it.
pub fn orbitZoom(delta: f32) void {
    if (z3d.g_orbit.locked) return;
    const factor: f32 = if (delta > 0) 0.88 else 1.0 / 0.88;
    z3d.g_orbit.dist = @max(z3d.g_orbit.radius * 0.15, @min(z3d.g_orbit.radius * 40.0, z3d.g_orbit.dist * factor));
}
pub fn orbitCamPos() math.Vec3 {
    const cp = @cos(z3d.g_orbit.pitch);
    return .{
        .x = z3d.g_orbit.target[0] + z3d.g_orbit.dist * cp * @sin(z3d.g_orbit.yaw),
        .y = z3d.g_orbit.target[1] + z3d.g_orbit.dist * @sin(z3d.g_orbit.pitch),
        .z = z3d.g_orbit.target[2] + z3d.g_orbit.dist * cp * @cos(z3d.g_orbit.yaw),
    };
}

/// Extend an automatic Studio far plane to contain one mesh bounding sphere.
/// WASD translates the orbit eye and target together, so `orbit.dist` alone no
/// longer describes how far resident geometry is from the camera.
pub fn orbitFarCoverSphere(current_far: f32, eye: math.Vec3, center: math.Vec3, radius_raw: f32) f32 {
    const radius = @max(0.0, radius_raw);
    const padding = @max(
        ORBIT_CLIP_TUNING.minimum_surface_padding,
        radius * ORBIT_CLIP_TUNING.surface_padding_radii,
    );
    return @max(current_far, math.v3distance(eye, center) + radius + padding);
}
/// Pan the orbit PIVOT in the screen plane by a drag delta (pixels). The orbit point was
/// nailed to the model centre, which fights you the moment a model is large — you'd
/// orbit a far edge around a centre half a model away. Moving the focus (not the eye)
/// lets you drop the centre of rotation right where you're working (req_2148). Speed
/// scales with dist so the grab tracks the cursor at any zoom; drag follows the content.
pub fn orbitPan(dx: f32, dy: f32) void {
    if (z3d.g_orbit.locked) return;
    const eye = z3d.orbitCamPos();
    const tgt = math.Vec3{ .x = z3d.g_orbit.target[0], .y = z3d.g_orbit.target[1], .z = z3d.g_orbit.target[2] };
    const fwd = math.v3normalize(math.v3sub(tgt, eye));
    const right = math.v3normalize(math.v3cross(fwd, math.v3up()));
    const up = math.v3cross(right, fwd);
    const k = z3d.g_orbit.dist * 0.0018;
    z3d.g_orbit.target[0] += -dx * k * right.x + dy * k * up.x;
    z3d.g_orbit.target[1] += -dx * k * right.y + dy * k * up.y;
    z3d.g_orbit.target[2] += -dx * k * right.z + dy * k * up.z;
}
/// Snap the orbit pivot to an explicit world point — keeps yaw/pitch/dist, so only the
/// centre of attention moves. The programmatic recentre (e.g. focus on a selection).
pub fn orbitFocus(p: [3]f32) void {
    z3d.g_orbit.target = p;
}
/// Re-centre the orbit on whatever the camera ray through (mx,my) hits — double-click a
/// far corner and it becomes the pivot. Returns false on a miss (empty space) so the cart
/// keeps the current focus. Uses the exact last-drawn camera, like paintAt.
pub fn focusAt(mx: f32, my: f32) bool {
    if (z3d.g_orbit.locked) return false;
    if (!model_paint.hasTarget()) return false;
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    const p = model_paint.pickPoint(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, z3d.vpLocalX(mx), z3d.vpLocalY(my)) orelse return false;
    z3d.g_orbit.target = p;
    return true;
}
pub inline fn vpLocalX(mx: f32) f32 {
    return mx - z3d.g_paint_vp_x;
}
pub inline fn vpLocalY(my: f32) f32 {
    return my - z3d.g_paint_vp_y;
}

test "Studio orbit navigation exclusively captures held WASD and moves camera-relative" {
    const saved_orbit = z3d.g_orbit;
    const saved_capture = z3d.g_me_capture;
    defer {
        z3d.g_orbit = saved_orbit;
        z3d.g_me_capture = saved_capture;
    }
    z3d.g_orbit = .{ .yaw = 0, .dist = 10, .radius = 1 };
    z3d.g_me_capture = true;

    try std.testing.expect(orbitNavigationSet(true));
    try std.testing.expect(orbitNavigationKey('w', true, false, false));
    try std.testing.expect(!orbitNavigationKey('q', true, false, false));
    try std.testing.expect(orbitNavigationTick(ORBIT_NAVIGATION_TUNING.maximum_step_seconds));
    try std.testing.expectApproxEqAbs(@as(f32, 0), z3d.g_orbit.target[0], 0.00001);
    try std.testing.expectApproxEqAbs(@as(f32, -0.35), z3d.g_orbit.target[2], 0.00001);

    try std.testing.expect(orbitNavigationKey('w', false, false, false));
    const stopped = z3d.g_orbit.target;
    try std.testing.expect(!orbitNavigationTick(ORBIT_NAVIGATION_TUNING.maximum_step_seconds));
    try std.testing.expectEqual(stopped, z3d.g_orbit.target);

    try std.testing.expect(!orbitNavigationSet(false));
    try std.testing.expect(!orbitNavigationKey('w', true, false, false));
}

test "Studio orbit navigation normalizes three-axis diagonals and respects camera lock" {
    const saved_orbit = z3d.g_orbit;
    const saved_capture = z3d.g_me_capture;
    defer {
        z3d.g_orbit = saved_orbit;
        z3d.g_me_capture = saved_capture;
    }
    z3d.g_orbit = .{ .yaw = 0, .dist = 10, .radius = 1 };
    z3d.g_me_capture = true;
    _ = orbitNavigationSet(true);
    _ = orbitNavigationKey('w', true, false, false);
    _ = orbitNavigationKey('d', true, false, false);
    _ = orbitNavigationKey('z', true, false, false);
    try std.testing.expect(orbitNavigationTick(ORBIT_NAVIGATION_TUNING.maximum_step_seconds));
    const traveled = @sqrt(
        z3d.g_orbit.target[0] * z3d.g_orbit.target[0] +
            z3d.g_orbit.target[1] * z3d.g_orbit.target[1] +
            z3d.g_orbit.target[2] * z3d.g_orbit.target[2],
    );
    try std.testing.expectApproxEqAbs(@as(f32, 0.35), traveled, 0.00001);

    z3d.g_orbit.locked = true;
    const locked = z3d.g_orbit.target;
    try std.testing.expect(!orbitNavigationTick(ORBIT_NAVIGATION_TUNING.maximum_step_seconds));
    try std.testing.expectEqual(locked, z3d.g_orbit.target);
    // Lock freezes camera motion, not the exclusive input contract.
    try std.testing.expect(orbitNavigationKey('d', false, false, false));
}

test "Studio orbit navigation modifiers provide traverse and precision speeds" {
    const saved_orbit = z3d.g_orbit;
    const saved_capture = z3d.g_me_capture;
    defer {
        z3d.g_orbit = saved_orbit;
        z3d.g_me_capture = saved_capture;
    }
    z3d.g_me_capture = true;

    z3d.g_orbit = .{ .yaw = 0, .dist = 10, .radius = 1 };
    _ = orbitNavigationSet(true);
    _ = orbitNavigationKey('w', true, true, false);
    try std.testing.expect(orbitNavigationTick(ORBIT_NAVIGATION_TUNING.maximum_step_seconds));
    const fast_distance = -z3d.g_orbit.target[2];

    z3d.g_orbit = .{ .yaw = 0, .dist = 10, .radius = 1 };
    _ = orbitNavigationSet(true);
    _ = orbitNavigationKey('w', true, false, true);
    try std.testing.expect(orbitNavigationTick(ORBIT_NAVIGATION_TUNING.maximum_step_seconds));
    const precision_distance = -z3d.g_orbit.target[2];

    try std.testing.expectApproxEqAbs(@as(f32, 1.4), fast_distance, 0.00001);
    try std.testing.expectApproxEqAbs(@as(f32, 0.0525), precision_distance, 0.00001);
    try std.testing.expect(fast_distance > precision_distance);

    // Modifier releases are transported even though they are not WASD and are
    // therefore not consumed. The next held-key tick must immediately be normal.
    z3d.g_orbit = .{ .yaw = 0, .dist = 10, .radius = 1 };
    _ = orbitNavigationSet(true);
    _ = orbitNavigationKey('w', true, true, false);
    try std.testing.expect(!orbitNavigationKey('q', false, false, false));
    try std.testing.expect(orbitNavigationTick(ORBIT_NAVIGATION_TUNING.maximum_step_seconds));
    try std.testing.expectApproxEqAbs(@as(f32, 0.35), -z3d.g_orbit.target[2], 0.00001);

    // Tab's mode boundary clears every axis/modifier. Normal middle-drag orbit
    // keeps its original pixel rate after fast navigation has been disabled.
    _ = orbitNavigationKey('q', true, true, false);
    try std.testing.expect(!orbitNavigationSet(false));
    try std.testing.expectEqual(@as(u8, 0), z3d.g_orbit.navigation_keys);
    try std.testing.expect(!z3d.g_orbit.navigation_shift);
    const yaw_before = z3d.g_orbit.yaw;
    orbitDrag(10, 0);
    try std.testing.expectApproxEqAbs(yaw_before - 0.1, z3d.g_orbit.yaw, 0.00001);
}

test "Studio orbit navigation Z rises and X descends on world Y" {
    const saved_orbit = z3d.g_orbit;
    const saved_capture = z3d.g_me_capture;
    defer {
        z3d.g_orbit = saved_orbit;
        z3d.g_me_capture = saved_capture;
    }
    z3d.g_orbit = .{ .yaw = 1.2, .pitch = 0.8, .dist = 10, .radius = 1 };
    z3d.g_me_capture = true;
    _ = orbitNavigationSet(true);

    try std.testing.expect(orbitNavigationKey('z', true, false, false));
    try std.testing.expect(orbitNavigationTick(ORBIT_NAVIGATION_TUNING.maximum_step_seconds));
    try std.testing.expectApproxEqAbs(@as(f32, 0.35), z3d.g_orbit.target[1], 0.00001);
    try std.testing.expectApproxEqAbs(@as(f32, 0), z3d.g_orbit.target[0], 0.00001);
    try std.testing.expectApproxEqAbs(@as(f32, 0), z3d.g_orbit.target[2], 0.00001);

    _ = orbitNavigationKey('z', false, false, false);
    try std.testing.expect(orbitNavigationKey('x', true, false, false));
    try std.testing.expect(orbitNavigationTick(ORBIT_NAVIGATION_TUNING.maximum_step_seconds));
    try std.testing.expectApproxEqAbs(@as(f32, 0), z3d.g_orbit.target[1], 0.00001);
}

test "Studio automatic far plane follows translated camera distance from mesh" {
    const model_center = math.Vec3{ .x = 0, .y = 0.5, .z = 0 };
    const model_radius: f32 = 0.75;
    const near_eye = math.Vec3{ .x = 0, .y = 0.5, .z = 3 };
    const walked_eye = math.Vec3{ .x = 0, .y = 0.5, .z = 40 };

    const initial_far = orbitFarCoverSphere(6, near_eye, model_center, model_radius);
    try std.testing.expectApproxEqAbs(@as(f32, 6), initial_far, 0.00001);

    const walked_far = orbitFarCoverSphere(initial_far, walked_eye, model_center, model_radius);
    const farthest_surface = math.v3distance(walked_eye, model_center) + model_radius;
    try std.testing.expect(walked_far > farthest_surface);
    try std.testing.expect(walked_far > initial_far);
}
